"""Original, fully populated fictional dossiers, separate from Nora's real-data prompts.

No real customer records or third-party template text are used here. Each family
has its own narrative; short instruments include a useful supporting dossier.
"""
from __future__ import annotations

import html
import re
import unicodedata


def normalized(value: str) -> str:
    return "".join(c for c in unicodedata.normalize("NFKD", value.casefold()) if not unicodedata.combining(c))


def paragraphs(*values: str) -> str:
    return "".join(f"<p>{html.escape(value)}</p>" for value in values)


def bullets(*values: str) -> str:
    return "<ul>" + "".join(f"<li>{html.escape(value)}</li>" for value in values) + "</ul>"


def table(headers: tuple[str, ...], rows: list[tuple[str, ...]]) -> str:
    return "<table><thead><tr>" + "".join(f"<th>{html.escape(v)}</th>" for v in headers) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{html.escape(v)}</td>" for v in row) + "</tr>" for row in rows) + "</tbody></table>"


def section(title: str, *text: str, extra: str = "") -> str:
    return f"<h2>{html.escape(title)}</h2>" + paragraphs(*text) + extra


def project_context(name: str, focus: str) -> tuple[str, str, list[str]]:
    key = normalized(name)
    topics = [v.strip(" .") for v in re.split(r",|;", focus) if len(v.strip()) > 3]
    if any(x in key for x in ("obra", "reforma", "arquitet", "engenharia", "pintura", "telhado", "piso", "gesso", "marcenaria", "predial", "solar", "cftv", "limpeza", "vidra", "climat", "hidraul", "imperme", "cortina")):
        return "modernização da unidade Aurora Centro", "Uma unidade comercial de 180 m², com salão, recepção, duas salas e área de apoio, precisa ser preparada para uma operação de 24 pessoas. A intervenção será organizada por ambientes, mantendo isoladas as áreas ainda em uso e registrando a situação inicial antes de qualquer intervenção.", topics
    if any(x in key for x in ("evento", "patrocin", "buffet", "fotograf", "video", "audiovisual")):
        return "Encontro Aurora de Negócios", "O encontro reunirá 120 convidados em 24/11/2026, das 9h às 18h, no Espaço Horizonte, local fictício em São Paulo. A programação combina recepção, três painéis, intervalo de relacionamento e apresentação de projetos. O acesso, a experiência do público e a documentação das entregas são prioridades do trabalho.", topics
    if any(x in key for x in ("marketing", "social", "trafego", "brand", "design", "conteudo", "identidade")):
        return "lançamento da coleção Aurora Essencial", "A Aurora Café & Co. prepara uma linha de kits de café para presentes corporativos. O piloto terá 60 dias, com catálogo de seis produtos e foco em compradores de pequenas empresas. A comunicação atual apresenta preços sem explicar origem, personalização e prazo de entrega, dificultando a comparação e a solicitação de orçamento.", topics
    if any(x in key for x in ("treinamento", "capacit", "rh", "recruta", "equipe")):
        return "programa Aurora de desenvolvimento de equipes", "A empresa reúne 24 profissionais e quatro lideranças. Entrevistas internas demonstrativas apontam falhas na passagem de demandas e critérios diferentes para avaliar entregas. O programa atenderá duas turmas de 12 participantes, com exercícios aplicados à rotina e acompanhamento das lideranças após a atividade principal.", topics
    if any(x in key for x in ("frete", "transport", "logistic", "armazen")):
        return "operação piloto de distribuição Aurora", "O piloto contempla 60 volumes de materiais não perecíveis, organizados em três lotes semanais entre dois endereços fictícios na região de São Paulo. O embarcador fornece a relação de volumes, pesos e restrições de manuseio. A conferência na origem e a evidência de recebimento no destino são requisitos de cada viagem.", topics
    return "projeto Aurora de melhoria da operação", "A Aurora Café & Co. recebe 240 solicitações mensais, distribuídas entre e-mail, formulários e atendimento presencial. O diagnóstico demonstrativo encontrou registros duplicados e ausência de um responsável claro por etapa. O projeto organiza o fluxo para que cada solicitação tenha identificação, prazo, histórico e evidência de conclusão.", topics


def commercial_example(name: str, focus: str) -> str:
    project, context, topics = project_context(name, focus)
    topics = topics[:6] or ["levantamento inicial", "planejamento", "produção das entregas", "revisão", "implantação", "acompanhamento"]
    result = section("01 · Carta de apresentação e resumo executivo",
        f"À Aurora Café & Co., aos cuidados de Marina Costa. O Estúdio Horizonte apresenta esta proposta para o {project}. A versão 1.0 foi preparada em 02/10/2026 após uma reunião de levantamento em 29/09/2026. Nosso compromisso é transformar a necessidade apresentada em entregas verificáveis, com responsáveis definidos e comunicação transparente ao longo da execução.",
        context,
        "A recomendação é executar um primeiro ciclo de seis semanas. Esse período permite confirmar premissas, produzir os materiais prioritários, validar o resultado em uma amostra controlada e transferir a rotina à equipe. O investimento demonstrativo é de R$ 12.800,00. A ampliação para outras unidades ou públicos será avaliada após o encerramento, sem contratação automática.")
    result += section("02 · Diagnóstico, objetivos e resultado esperado",
        "Foram considerados três problemas no cenário de exemplo: informações de entrada incompletas, aprovações dispersas e dificuldade de comprovar o que foi entregue. Hoje, cada responsável usa seu próprio controle. Isso gera retrabalho e torna a programação dependente de conversas que não ficam registradas. A solução proposta combina organização do trabalho, validações intermediárias e um pacote final de evidências.",
        "O objetivo principal é concluir o piloto com 100% das entregas prioritárias documentadas e aprovadas. Como metas auxiliares, propõe-se reduzir a devolução por informação ausente de 20% para 10% e atingir satisfação de pelo menos 4 em 5 na avaliação dos participantes. Esses números são metas do cenário fictício, não garantias de desempenho comercial.",
        "A comparação usará a mesma definição de solicitação, o mesmo período de observação e uma amostra mínima de 30 registros por ciclo. Mudanças de volume, de equipe ou de contexto serão anotadas no relatório final para não atribuir ao projeto efeitos que dependam de fatores externos.")
    result += section("03 · Escopo técnico e pacote de entregas",
        f"O trabalho está organizado nos seguintes eixos: {', '.join(topics)}. Cada eixo terá uma versão de trabalho, uma revisão consolidada e uma versão de entrega. O ponto focal do cliente receberá os arquivos em formato editável e uma cópia de leitura em PDF, acompanhadas de um índice que relacione requisito, material produzido e responsável pelo aceite.",
        "Antes da produção, serão confirmados dimensões, quantidades, acessos, fontes e requisitos aplicáveis. Nenhuma decisão irreversível será tomada apenas com base em uma ilustração do modelo. As especificações finais serão registradas na ficha de levantamento e incorporadas à versão aprovada do escopo.",
        extra=bullets(*[f"{topic.capitalize()}: {detail}" for topic, detail in zip(topics, (
            "reunião de levantamento, organização das referências e registro das premissas. A entrega inclui ficha de diagnóstico com situação atual, necessidade prioritária e pontos que exigem confirmação antes da produção.",
            "preparação de duas alternativas com justificativa, vantagens, restrições e impacto estimado. A escolha será registrada por Marina antes do desenvolvimento, evitando produzir versões completas de soluções ainda não aprovadas.",
            "desenvolvimento da alternativa escolhida, acompanhado de especificações, lista de componentes e instruções de conferência. Os arquivos receberão identificação de versão e serão entregues em formato editável compatível com a finalidade.",
            "revisão cruzada entre requisitos e materiais produzidos, com lista de interferências, inconsistências e ajustes. Rafael consolida o retorno e apresenta a versão corrigida, indicando quais pontos foram alterados e quais permanecem dependentes de decisão.",
            "validação em uma amostra controlada, com critérios definidos antes do teste. A equipe registra condições, evidências e limitações, corrige falhas identificadas e obtém manifestação do responsável sobre o resultado.",
            "entrega assistida e transferência do conhecimento, incluindo índice de arquivos, orientações de manutenção e reunião de encerramento. O cliente recebe a relação de pendências residuais, quando houver, com responsável e data combinada.",
        ))]))
    result += section("04 · Método de trabalho e controles de qualidade",
        "Na primeira semana, a equipe realiza uma oficina de 90 minutos e revisa até 30 registros ou referências fornecidos pelo cliente. O resultado é uma matriz de prioridades com critérios objetivos: impacto na operação, dependências, esforço e urgência. A sequência de execução será confirmada antes de iniciar a produção principal.",
        "A produção ocorrerá em dois ciclos curtos. Ao fim de cada ciclo, o Estúdio Horizonte apresentará as entregas em reunião de até 45 minutos. O cliente consolidará os comentários em um único documento para evitar orientações conflitantes. Estão incluídas duas rodadas de ajustes dentro do escopo aprovado; mudança de objetivo, quantidade ou formato será avaliada separadamente.",
        "A revisão final verifica integridade dos arquivos, coerência entre versões, legibilidade, correspondência com o briefing e atendimento aos critérios de aceite. Defeitos identificados nessa conferência serão corrigidos antes do encerramento. O histórico de revisão permanece disponível no pacote de entrega para permitir rastreabilidade.")
    result += section("05 · Cronograma e marcos de aprovação",
        "O calendário pressupõe aprovação até 09/10/2026 e início em 12/10/2026. A previsão de conclusão é 20/11/2026. As datas são demonstrativas e deverão ser ajustadas à disponibilidade das partes, dos ambientes e dos fornecedores. O cliente terá até dois dias úteis para responder a cada pedido consolidado de aprovação.",
        extra=table(("Período", "Entrega", "Responsável / aprovação"), [
            ("12–16/10", "Levantamento, premissas e prioridades", "Marina Costa / Aurora"),
            ("19–23/10", "Conceito e especificações detalhadas", "Rafael Lima / Horizonte"),
            ("26/10–06/11", "Produção e revisão intermediária", "Equipe técnica / Marina"),
            ("09–13/11", "Validação do piloto e correções", "Rafael e usuários convidados"),
            ("16–20/11", "Entrega editável, orientação e aceite", "Marina e Rafael"),
        ]))
    result += section("06 · Equipe, responsabilidades e comunicação",
        "Rafael Lima será responsável pelo planejamento, pela coordenação técnica e pela consolidação do relatório semanal. Marina Costa representará a Aurora nas decisões de negócio, reunirá os materiais de entrada e indicará os participantes das validações. Beatriz Almeida fará a revisão independente dos materiais finais, sem substituir o aceite do cliente.",
        "As atualizações ocorrerão às sextas-feiras, com resumo do concluído, trabalho seguinte e decisões pendentes. O canal demonstrativo é projetos@horizonte.example. Decisões que alterem preço, prazo ou escopo precisam constar de uma confirmação escrita identificada pela versão da proposta. Conversas operacionais não serão tratadas como autorização financeira.")
    result += section("07 · Investimento discriminado e condições de pagamento",
        "O preço global cobre a execução descrita, a coordenação e as duas rodadas de revisão. Os valores abaixo compõem o total de R$ 12.800,00 e permitem compreender a distribuição do esforço. Nenhuma despesa adicional será assumida em nome do cliente sem orçamento específico e aprovação prévia.",
        extra=table(("Componente", "Quantidade × valor", "Subtotal"), [
            ("Diagnóstico e planejamento", "12 h × R$ 200,00", "R$ 2.400,00"),
            ("Produção especializada", "36 h × R$ 200,00", "R$ 7.200,00"),
            ("Validação e documentação", "12 h × R$ 200,00", "R$ 2.400,00"),
            ("Transferência e orientação", "4 h × R$ 200,00", "R$ 800,00"),
            ("TOTAL", "64 horas", "R$ 12.800,00"),
        ]) + paragraphs("A primeira parcela de R$ 6.400,00 vence em 09/10/2026, após a aprovação. A segunda, de R$ 6.400,00, vence em 20/11/2026, vinculada à disponibilização do pacote final. Esta simulação não contém chave de pagamento válida. A emissão fiscal e o tratamento tributário serão definidos conforme a contratação real e a orientação contábil aplicável."))
    result += section("08 · Premissas, exclusões e dependências",
        "A Aurora fornecerá dados revisados, acesso aos ambientes necessários e autorização sobre materiais disponibilizados. O preço considera uma unidade, um ponto focal e o conjunto de entregas indicado. Aquisição de equipamentos, licenças, mídia paga, obras adicionais, viagens e taxas de terceiros não estão incluídas, salvo quando incorporadas expressamente à contratação real.",
        "Se houver impedimento externo, o responsável informará causa, impacto e alternativa em até um dia útil após a identificação. A reprogramação será registrada em calendário revisado. O silêncio do cliente não será utilizado como aprovação de uma despesa ou aceitação de uma entrega que dependa de manifestação expressa.")
    result += section("09 · Riscos e plano de resposta",
        "O principal risco é iniciar a produção com informações incompletas. Para reduzi-lo, a equipe usará uma lista de entrada obrigatória e validará os itens críticos antes do segundo marco. Outro risco é a concentração de aprovações em uma pessoa indisponível; Marina indicará um substituto durante o início do projeto.",
        extra=table(("Risco", "Prevenção", "Resposta"), [
            ("Atraso na entrega de insumos", "Lista de entrada e cobrança antecipada", "Reordenar atividades sem elevar custo automaticamente"),
            ("Mudança de requisito", "Versão de referência aprovada", "Analisar impacto e apresentar aditivo de escopo"),
            ("Resultado abaixo da meta", "Piloto e avaliação intermediária", "Corrigir causa e registrar novo teste"),
        ]))
    result += section("10 · Aceite, transição e próximos passos",
        "O aceite considera quatro evidências: materiais completos, arquivos editáveis abertos sem erro, requisitos prioritários atendidos e orientação de uso realizada. Comentários de preferência posteriores ao aceite não anulam entregas conformes; serão avaliados como uma nova solicitação. Pendências identificadas antes da conclusão serão listadas com responsável e data de correção.",
        "Após a entrega, estão previstas duas sessões remotas de uma hora para orientar a equipe e esclarecer o conteúdo. O acompanhamento demonstrativo termina em 04/12/2026. A manutenção contínua ou uma nova fase pode ser proposta, mas não é requisito para que o cliente utilize os materiais recebidos.",
        "Esta proposta é válida até 09/10/2026. Para seguir, Marina confirma escopo, calendário e condições comerciais; Rafael envia a versão aprovada e agenda a reunião inicial. Espaço de manifestação: Marina Costa, pela Aurora Café & Co.; Rafael Lima, pelo Estúdio Horizonte. Nomes e assinaturas deste exemplo não representam concordância de pessoas reais.")
    return result


def resume_example(name: str) -> str:
    key = normalized(name)
    junior = "primeiro emprego" in key
    academic = "academico" in key
    creative = "criativo" in key
    technical = "tecnologia" in key
    executive = "executivo" in key
    transition = "transicao" in key
    role = "Assistente administrativa" if junior else "Pesquisadora em aprendizagem digital" if academic else "Designer de produto" if creative else "Engenheira de software" if technical else "Diretora de operações" if executive else "Analista de dados e operações" if transition else "Gerente de produto digital"
    result = section("Marina Costa · " + role,
        "São Paulo, SP · marina.costa@candidata.example · portfólio: marina.example · disponibilidade para trabalho híbrido. Contato e endereço eletrônico são demonstrativos e não correspondem a uma candidatura real. A imagem apresentada é um retrato ilustrado substituível por uma foto enviada pelo usuário.",
        ("Estudante de Administração com conclusão prevista para dezembro de 2026. Busco minha primeira oportunidade profissional para apoiar organização de documentos, atendimento e controles administrativos. Minha experiência vem de projetos acadêmicos e voluntariado; não possuo vínculo de emprego anterior." if junior else f"{role} com trajetória em projetos que aproximam necessidades das pessoas, decisões baseadas em dados e execução disciplinada. Atuo na definição do problema, na construção de soluções e no acompanhamento dos resultados, mantendo documentação acessível a áreas técnicas e de negócio. Busco contribuir em uma organização que valorize qualidade, colaboração e aprendizagem contínua."))
    result += section("Resumo de competências e proposta de valor",
        ("Durante a formação, desenvolvi organização de planilhas, redação de comunicações, apresentação de resultados e colaboração em pequenos grupos. Tenho facilidade para aprender ferramentas digitais e sigo instruções de conferência para reduzir erros em tarefas repetitivas. Em atividades voluntárias, aprendi a ouvir a demanda antes de indicar uma solução e a encaminhar dúvidas que ultrapassam minha responsabilidade." if junior else "Minha atuação combina análise estruturada, comunicação clara e capacidade de transformar problemas amplos em entregas menores. Facilito reuniões de alinhamento, organizo critérios de priorização e acompanho indicadores sem perder de vista as limitações da amostra. Procuro documentar decisões importantes para que a equipe possa compreender o contexto e continuar o trabalho com autonomia."),
        ("Em tecnologia, trabalho com Python, TypeScript, SQL, testes automatizados e revisão de código. Participo de decisões de arquitetura considerando manutenção, segurança, observabilidade e custo operacional. A experiência descrita abaixo inclui implementação e acompanhamento da solução em uso, e não apenas protótipos." if technical else "Tenho experiência demonstrativa com planilhas, apresentações, organização de projetos e síntese de informações. Uso esses recursos para tornar o trabalho visível, combinar responsabilidades e reduzir ruídos na passagem de atividades. Os exemplos deste currículo foram escritos para mostrar como relacionar competências a situações concretas, sem depender de adjetivos genéricos."))
    employer = "Instituto Horizonte · projetos acadêmicos" if junior or academic else "Aurora Labs · empresa fictícia"
    result += section("Experiência principal · " + employer,
        ("Março de 2025 a setembro de 2026 — integrante de projetos de extensão e organização estudantil. Apoiei uma equipe de quatro alunos na preparação de oficinas de educação financeira e na organização de inscrições, materiais e listas de presença. A responsabilidade foi voluntária e supervisionada, sem contratação profissional." if junior else f"Janeiro de 2023 a setembro de 2026 — {role}. Atuação em uma operação com 24 profissionais, atendendo três áreas internas. Responsável por estruturar o acompanhamento de solicitações, facilitar decisões com as lideranças e transformar necessidades recorrentes em melhorias documentadas. Trabalho realizado em conjunto com atendimento, tecnologia e gestão."),
        extra=bullets(
            "Organizei um diagnóstico com 18 entrevistas e análise de 120 registros, consolidando problemas por frequência e impacto. O material permitiu separar dificuldades de processo de solicitações pontuais e foi usado para definir o primeiro ciclo de melhoria.",
            "Estruturei um quadro de prioridades com critérios explícitos, responsáveis e datas de revisão. A equipe passou a discutir decisões com base em evidências e dependências, preservando um histórico das escolhas e das alternativas descartadas.",
            "Preparei um guia de execução com exemplos, perguntas frequentes e critérios de conferência. O guia foi validado por cinco participantes antes da distribuição e recebeu uma revisão após o primeiro mês de uso.",
        ))
    result += section("Trajetória anterior e progressão",
        ("Agosto de 2024 a fevereiro de 2025 — voluntária no Coletivo Ponte, organização fictícia. Organizei a agenda de oito encontros, preparei materiais de apoio e acompanhei a confirmação de presença. Ao final de cada encontro, consolidei dúvidas e encaminhamentos para a coordenação. Essa atividade desenvolveu pontualidade, escrita objetiva e responsabilidade sobre informações de outras pessoas." if junior else "Fevereiro de 2020 a dezembro de 2022 — analista de projetos no Estúdio Horizonte, empresa fictícia. Apoiei seis projetos de melhoria, desde o levantamento inicial até a entrega dos materiais. Preparei atas, organizei o controle de versões e acompanhei pendências com clientes internos. A evolução para maior autonomia ocorreu após assumir a coordenação de um piloto com três participantes de áreas diferentes."),
        "Um aprendizado importante dessa etapa foi distinguir conclusão de uma tarefa de resultado para o usuário. Passei a registrar como a entrega seria utilizada, quem deveria validá-la e que evidência demonstraria o atendimento da necessidade. Também aprendi a comunicar atrasos cedo, propondo alternativas e explicando as dependências envolvidas.")
    result += section("Projeto selecionado 1 · Jornada de atendimento Aurora",
        "Problema: solicitações chegavam por três canais, com informações incompletas e sem acompanhamento uniforme. Minha participação foi mapear o percurso, identificar pontos de perda e preparar um piloto de organização. A equipe criou um formulário de entrada, definiu categorias de demanda e combinou regras para encaminhamento e retorno.",
        "Método: análise de 120 registros, entrevistas com seis participantes e teste de quatro semanas. A amostra demonstrativa registrou redução do retrabalho de 25 para 17 ocorrências, equivalente a 32%. O resultado foi apresentado com o tamanho da amostra e as limitações de comparação, sem atribuir causalidade a uma única mudança.",
        "Entregas: mapa da jornada, matriz de responsabilidades, guia de triagem e apresentação executiva. No portfólio fictício, o caso está descrito sem dados pessoais dos participantes. As competências evidenciadas são investigação, síntese, desenho de processo, comunicação e avaliação de resultado.")
    result += section("Projeto selecionado 2 · Biblioteca de conhecimento",
        "Contexto: materiais de orientação estavam distribuídos em pastas com nomes diferentes. A proposta foi organizar uma biblioteca com 40 conteúdos, classificação por tema e indicação da última revisão. Defini um padrão de título, resumo, responsável e critério de atualização, além de preparar os primeiros dez exemplos para orientar a equipe.",
        "Resultado demonstrativo: em um teste com oito participantes, o tempo mediano para localizar uma orientação passou de seis para três minutos. A biblioteca recebeu um roteiro de manutenção mensal para evitar que o ganho inicial se perdesse com o crescimento do conteúdo. Minha principal contribuição foi a organização da informação e a validação da experiência de consulta.")
    result += section("Formação e desenvolvimento contínuo",
        ("Bacharelado em Administração — Instituto Horizonte, instituição fictícia; início em 2023 e conclusão prevista em dezembro de 2026. Projetos relevantes: organização administrativa, análise de dados em planilhas e comunicação empresarial. Trabalho final em desenvolvimento sobre padronização de rotinas em pequenos negócios." if junior else "Graduação em Gestão e Tecnologia — Instituto Horizonte, instituição fictícia, 2016–2019. Projeto final: melhoria do fluxo de atendimento em pequenos negócios. Especialização demonstrativa em gestão de projetos e análise de dados, concluída em 2022, com aplicação prática em planejamento, indicadores e avaliação de resultados."),
        "Cursos complementares fictícios: Análise de Dados Aplicada, 40 horas, 2024; Facilitação de Reuniões, 16 horas, 2025; Comunicação de Resultados, 20 horas, 2026. O estudo contínuo é acompanhado por registros de aplicação: uma planilha revisada, uma reunião facilitada ou uma apresentação aprimorada após feedback.")
    if academic:
        result += section("Pesquisa, docência e produção acadêmica demonstrativa",
            "Linha de pesquisa: aprendizagem digital em equipes de pequenos negócios. Participei da construção de instrumentos de observação e da organização de resultados de oficinas. O material didático foi revisado para apresentar instruções em linguagem simples e atividades com diferentes níveis de dificuldade.",
            "Produção fictícia: Costa, Marina. Organização do conhecimento em equipes de aprendizagem. Caderno Interno Horizonte, 2025. Esta referência é inventada para demonstrar formatação e não deve ser apresentada como publicação real. Atividades de docência incluem facilitação supervisionada de quatro oficinas de duas horas e preparação de rubricas de avaliação.")
    result += section("Ferramentas, idiomas e informações complementares",
        "Ferramentas: planilhas com tabelas dinâmicas e validação de dados; apresentações executivas; quadros de organização de projetos; documentação colaborativa. A proficiência deve ser ajustada à experiência real do candidato. Em uma entrevista, cada ferramenta pode ser relacionada a um projeto descrito neste currículo, evitando listas de tecnologias sem contexto.",
        "Idiomas no cenário fictício: português nativo e inglês avançado para leitura, escrita e reuniões de trabalho. Participação voluntária em mentoria de organização de estudos, com dois encontros mensais. Disponibilidade para início em novembro de 2026, a combinar conforme a oportunidade.",
        "Referências profissionais não são expostas neste modelo. Contatos de outras pessoas somente devem ser compartilhados com autorização. Antes de enviar a candidatura, revise o cargo-alvo, substitua todos os dados demonstrativos e mantenha apenas experiências, resultados, formações e links que possam ser comprovados.")
    return result


def finance_example(name: str, kind: str) -> str:
    receipt = kind == "receipt"
    result = section("01 · Identificação e objeto",
        f"{name} · referência EX-FIN-2026-024 · emissão em 20/11/2026. Emitente: Estúdio Horizonte, empresa fictícia, representada por Rafael Lima. Cliente: Aurora Café & Co., empresa fictícia, representada por Marina Costa. Contatos demonstrativos: financeiro@horizonte.example e contas@aurora.example. Todos os números e eventos deste documento pertencem a uma simulação.",
        ("Declaramos, exclusivamente para demonstrar a composição de um recibo, o recebimento de R$ 6.400,00 em 20/11/2026, referente à segunda parcela do projeto Aurora. A primeira parcela de igual valor foi registrada em 09/10/2026. O total demonstrativo recebido é de R$ 12.800,00. Esta declaração não comprova qualquer pagamento real." if receipt else "O documento discrimina o pacote de serviços do projeto Aurora, executado entre 12/10 e 20/11/2026. A referência de contratação é EX-024/2026, versão 1.0. O total é de R$ 12.800,00, composto por diagnóstico, produção, validação e transferência de conhecimento. O detalhamento permite comparar o solicitado, o entregue e o valor associado."),
        "Este modelo é administrativo e demonstrativo. Não substitui documento fiscal, comprovante bancário, escrituração ou orientação contábil. Não há conta, chave Pix, boleto ou código de pagamento válido no conteúdo. A versão final deverá utilizar os dados efetivos da operação e observar os procedimentos da organização.")
    result += section("02 · Discriminação dos itens",
        "A unidade de medida adotada é hora de trabalho especializado. O valor unitário demonstrativo de R$ 200,00 foi aplicado de forma uniforme para tornar a memória de cálculo transparente. Horas adicionais não fazem parte do total. A composição de uma contratação real pode utilizar unidades diferentes, desde que a quantidade e a base de preço estejam claras.",
        extra=table(("Descrição", "Quantidade", "Unitário", "Total"), [("Diagnóstico e planejamento", "12 h", "R$ 200,00", "R$ 2.400,00"), ("Produção especializada", "36 h", "R$ 200,00", "R$ 7.200,00"), ("Validação e documentação", "12 h", "R$ 200,00", "R$ 2.400,00"), ("Orientação de uso", "4 h", "R$ 200,00", "R$ 800,00"), ("Total", "64 h", "—", "R$ 12.800,00")]))
    result += section("03 · Memória de cálculo e conciliação",
        "Subtotal de serviços: R$ 12.800,00. Descontos comerciais: R$ 0,00. Despesas adicionais aprovadas: R$ 0,00. Total do pacote: R$ 12.800,00. O cálculo consiste na multiplicação de cada quantidade pelo valor unitário e na soma dos quatro subtotais. Não foram inseridos tributos fictícios com aparência de apuração fiscal.",
        "Controle de parcelas: R$ 6.400,00 em 09/10/2026 e R$ 6.400,00 em 20/11/2026. A soma das duas parcelas coincide com o total do pacote. No cenário de encerramento, ambas estão registradas como recebidas e o saldo comercial é de R$ 0,00. Em um orçamento anterior à execução, o mesmo quadro deverá indicar previsão, não pagamento realizado.",
        "A conciliação real exige comparação com o extrato e com os documentos de origem. Um status marcado manualmente não constitui prova de liquidação. Divergências de centavos, descontos ou compensações precisam ser explicadas em um lançamento identificável, sem alterar retroativamente o valor original do documento.")
    result += section("04 · Competência, entrega e conferência",
        "Os serviços de diagnóstico foram concluídos em 16/10/2026; a produção principal, em 06/11/2026; a validação, em 13/11/2026; e a orientação, em 20/11/2026. O responsável pela conferência foi Marina Costa. O pacote final contém relatório de levantamento, materiais editáveis, registro de revisão e instruções de uso.",
        "A conferência foi dividida em quantidade, conteúdo e documentação. Quantidade verifica a correspondência dos itens; conteúdo verifica a entrega contratada; documentação verifica referências, datas e responsáveis. Essa separação permite devolver um item incompleto sem perder o registro dos demais itens já conferidos.")
    result += section("05 · Condições e tratamento de divergências",
        "A comunicação de dúvida deverá informar a referência EX-FIN-2026-024, o item questionado e o valor que se pretende conferir. Rafael Lima reúne os documentos de origem e responde pelo canal financeiro demonstrativo. Marina Costa confirma o recebimento da resposta e registra a conclusão da conferência.",
        "Se houver erro material, será emitida versão corrigida com indicação do motivo, data e vínculo com a anterior. A cópia histórica permanecerá identificada como substituída. Não se deve apagar um documento já compartilhado nem reutilizar a mesma referência para uma operação diferente. Uma cobrança real só será enviada após verificar destinatário e dados de pagamento por canal confiável.")
    result += section("Anexo A · Relação de documentos de suporte",
        "EX-024/2026: proposta aprovada e descrição do pacote. EX-ENT-01: levantamento inicial. EX-ENT-02: índice dos arquivos produzidos. EX-REV-01: registro da revisão. EX-ACE-01: manifestação de recebimento. EX-PAG-01 e EX-PAG-02: referências ilustrativas das duas parcelas. Nenhum desses códigos consulta um sistema externo ou representa comprovante autêntico.",
        "O índice de suporte deve permitir localizar a evidência sem expor informações desnecessárias. Uma versão destinada ao cliente pode conter apenas o resumo e os documentos pertinentes à sua operação. Dados bancários completos, documentos pessoais e informações de outros clientes não integram esse pacote.")
    result += section("Anexo B · Registro de encerramento administrativo",
        "A pessoa responsável pelo arquivo manterá uma cópia de leitura da versão emitida e o conteúdo editável para eventual correção identificada. A organização dos comprovantes deve permitir reconstruir a operação sem depender da memória de quem participou.",
        "Em 20/11/2026, Rafael e Marina conferiram o quadro de itens, a soma das parcelas e o índice de entregas do cenário demonstrativo. Não foi identificada diferença no total. O encerramento administrativo não substitui análise técnica de qualidade nem declaração de quitação de obrigações que não estejam expressamente relacionadas neste documento.",
        "Responsável pela emissão: Rafael Lima. Responsável pela conferência: Marina Costa. Data de revisão: 20/11/2026. Assinaturas de composição: ____________________ e ____________________. Antes do uso real, substitua nomes, referências e valores, confira o enquadramento fiscal e remova o aviso de demonstração somente quando o conteúdo corresponder integralmente à operação efetiva.")
    return result


